RESULT_COLUMNS = ["SUBJECT_AREA","WORKFLOW_NAME","SESSION_INSTANCE_NAME","SESSION_NAME","MAPPING_NAME",
                  "MAPPLET_INSTANCE_NAME","MAPPLET_NAME","MAPPLET_INSTANCE_ID","MAPPLET_INSTANCE_WIDGET_ID",
                  "TRANSFORMATION_INSTANCE_ID","TRANSFORMATION_INSTANCE_NAME","TRANSFORMATION_WIDGET_ID",
                  "WIDGET_TYPE","WIDGET_TYPE_NAME","TRANSFORMATION_DESCRIPTION","TRANSFORMATION_VERSION"]

def configure_file_logging(path):
    """Create a fresh UTF-8 log file while retaining console logging."""
    p = Path(path)
    log.info("STEP 01.01 | Preparing log directory: %s", p.parent.resolve())
    p.parent.mkdir(parents=True, exist_ok=True)
    h = logging.FileHandler(p, mode="w", encoding="utf-8")
    h.setLevel(logging.INFO)
    h.setFormatter(logging.Formatter(LOG_FORMAT))
    logging.getLogger().addHandler(h)
    log.info("STEP 01.02 | File logging enabled: %s", p.resolve())
    return p


def load_config(path):
    p = Path(path)
    log.info("STEP 02.01 | Loading configuration: %s", p.resolve())
    if not p.exists():
        log.error("STEP 02.02 | Configuration file not found: %s", p.resolve())
        raise FileNotFoundError(f"Configuration file not found: {p}")
    with p.open(encoding="utf-8") as f:
        c = json.load(f)
    log.info("STEP 02.02 | Configuration JSON parsed successfully")
    missing = [k for k in ("user", "password", "dsn") if not c.get("db", {}).get(k)]
    if missing:
        log.error("STEP 02.03 | Missing configuration keys: %s", ", ".join("db." + k for k in missing))
        raise ValueError("Missing config: " + ", ".join("db." + k for k in missing))
    log.info("STEP 02.03 | Required database configuration validated")
    log.info("STEP 02.04 | Database DSN configured: %s", c["db"]["dsn"])
    log.info("STEP 02.05 | Oracle mode configured: %s", "thick" if c.get("thick_mode", {}).get("enabled", False) else "thin")
    return c


def normalize_schema_prefix(value):
    log.info("STEP 03.01 | Validating repository schema prefix")
    value = (value or "M2R_REP_1053_P01.").strip()
    if not value.endswith("."):
        value += "."
        log.info("STEP 03.02 | Appended trailing period to schema prefix")
    if not re.fullmatch(r"[A-Za-z][A-Za-z0-9_$#]*\.", value):
        log.error("STEP 03.03 | Invalid repository schema prefix: %r", value)
        raise ValueError("Invalid schema prefix")
    value = value.upper()
    log.info("STEP 03.03 | Repository schema validated: %s", value[:-1])
    return value


def read_mapplet_names(path):
    p = Path(path)
    log.info("STEP 04.01 | Reading mapplet input file: %s", p.resolve())
    if not p.exists():
        log.error("STEP 04.02 | Mapplet input file not found: %s", p.resolve())
        raise FileNotFoundError(f"Mapplet input file not found: {p}")
    result = []
    seen = set()
    ignored_blank = ignored_comment = ignored_duplicate = 0
    with p.open(encoding="utf-8-sig") as f:
        for line_number, raw in enumerate(f, start=1):
            name = raw.strip()
            if not name:
                ignored_blank += 1
                log.debug("STEP 04.02 | Ignoring blank line %d", line_number)
                continue
            if name.startswith("#"):
                ignored_comment += 1
                log.debug("STEP 04.03 | Ignoring comment line %d", line_number)
                continue
            if name.upper() in seen:
                ignored_duplicate += 1
                log.warning("STEP 04.04 | Ignoring duplicate mapplet at line %d: %s", line_number, name)
                continue
            seen.add(name.upper())
            result.append(name)
            log.info("STEP 04.05 | Loaded mapplet %d: %s", len(result), name)
    if not result:
        log.error("STEP 04.06 | No valid mapplet names found")
        raise ValueError("No mapplet names found")
    log.info("STEP 04.06 | Mapplet loading completed. Valid=%d, blank=%d, comments=%d, duplicates=%d",
             len(result), ignored_blank, ignored_comment, ignored_duplicate)
    return result


def connect(config):
    thick = config.get("thick_mode", {})
    mode = "thick" if thick.get("enabled", False) else "thin"
    log.info("STEP 05.01 | Initializing Oracle connection in %s mode", mode)
    if thick.get("enabled", False):
        lib_dir = thick.get("lib_dir") or None
        log.info("STEP 05.02 | Initializing Oracle client library. lib_dir=%s", lib_dir or "system default")
        oracledb.init_oracle_client(lib_dir=lib_dir)
    db = config["db"]
    log.info("STEP 05.03 | Connecting to Oracle DSN=%s as user=%s", db["dsn"], db["user"])
    started = time.monotonic()
    connection = oracledb.connect(user=db["user"], password=db["password"], dsn=db["dsn"])
    log.info("STEP 05.04 | Oracle connection established in %.2f seconds", time.monotonic() - started)
    return connection


def build_discovery_query(schema, all_mapplets=False):
    """Build discovery SQL for selected-mapplet or workflow-wide mode."""
    mode = "workflow all-mapplet" if all_mapplets else "selected-mapplet"
    log.info("STEP 06.01 | Building %s discovery query for schema %s", mode, schema[:-1])
    mapplet_filter = "" if all_mapplets else "WHERE UPPER(mp.MAPPLET_NAME)=UPPER(:mapplet_name)"
    sql = f"""
WITH workflow_mappings AS (
 SELECT DISTINCT s.SUBJECT_AREA,s.SUBJECT_ID,s.MAPPING_ID,s.MAPPING_NAME,w.WORKFLOW_NAME,
        ti.INSTANCE_NAME SESSION_INSTANCE_NAME,s.SESSION_NAME
 FROM {schema}REP_WORKFLOWS w
 JOIN {schema}REP_TASK_INST ti ON ti.WORKFLOW_ID=w.WORKFLOW_ID AND ti.TASK_TYPE=68
 JOIN {schema}REP_LOAD_SESSIONS s ON s.SESSION_ID=ti.TASK_ID AND s.SUBJECT_ID=w.SUBJECT_ID
 WHERE w.SUBJECT_AREA=:subject_area AND w.WORKFLOW_NAME=:workflow_name
), mapping_mapplets AS (
 SELECT DISTINCT wm.SUBJECT_AREA,wm.WORKFLOW_NAME,wm.SESSION_INSTANCE_NAME,wm.SESSION_NAME,
        wm.MAPPING_ID,wm.MAPPING_NAME,mpi.INSTANCE_ID MAPPLET_INSTANCE_ID,
        mpi.INSTANCE_NAME MAPPLET_INSTANCE_NAME,mpi.WIDGET_ID MAPPLET_INSTANCE_WIDGET_ID,
        mp.MAPPLET_NAME,mp.PARENT_MAPPLET_ID MAPPLET_DEFINITION_ID,
        mp.SUBJECT_ID MAPPLET_SUBJECT_ID,mp.PARENT_MAPPLET_VERSION_NUMBER MAPPLET_VERSION_NUMBER
 FROM workflow_mappings wm
 JOIN {schema}REP_WIDGET_INST mpi ON mpi.MAPPING_ID=wm.MAPPING_ID AND mpi.SUBJECT_ID=wm.SUBJECT_ID AND mpi.WIDGET_TYPE=44
 JOIN {schema}REP_ALL_MAPPLETS mp ON mp.REF_WIDGET_ID=mpi.WIDGET_ID AND mp.SUBJECT_ID=mpi.SUBJECT_ID
 {mapplet_filter}
)
SELECT mm.SUBJECT_AREA,mm.WORKFLOW_NAME,mm.SESSION_INSTANCE_NAME,mm.SESSION_NAME,mm.MAPPING_NAME,
       mm.MAPPLET_INSTANCE_NAME,mm.MAPPLET_NAME,mm.MAPPLET_INSTANCE_ID,mm.MAPPLET_INSTANCE_WIDGET_ID,
       mt.INSTANCE_ID TRANSFORMATION_INSTANCE_ID,mt.INSTANCE_NAME TRANSFORMATION_INSTANCE_NAME,
       mt.WIDGET_ID TRANSFORMATION_WIDGET_ID,mt.WIDGET_TYPE,mt.WIDGET_TYPE_NAME,
       mt.DESCRIPTION TRANSFORMATION_DESCRIPTION,mt.VERSION_NUMBER TRANSFORMATION_VERSION
FROM mapping_mapplets mm
JOIN {schema}REP_WIDGET_INST mt ON mt.MAPPING_ID=mm.MAPPLET_DEFINITION_ID
 AND mt.SUBJECT_ID=mm.MAPPLET_SUBJECT_ID AND mt.VERSION_NUMBER=mm.MAPPLET_VERSION_NUMBER
ORDER BY mm.MAPPLET_NAME,mm.MAPPLET_INSTANCE_NAME,mt.WIDGET_TYPE_NAME,mt.INSTANCE_NAME
"""
    log.info("STEP 06.02 | Discovery query built. mode=%s, characters=%d", mode, len(sql))
    return sql


def prepare_excel_query(raw_sql, schema):
    log.info("STEP 07.01 | Preparing transformation-specific SQL")
    if not raw_sql or not str(raw_sql).strip():
        raise ValueError("Transformation query is empty or not present in the script")
    sql = str(raw_sql).strip().rstrip(";")
    original_length = len(sql)
    # Replace repository schema prefixes and literal runtime filters generically.
    # No subject area, workflow name, mapplet name, or repository schema value is hardcoded.
    sql, schema_count = re.subn(
        r"\b[A-Za-z][A-Za-z0-9_$#]*\.(?=(?:REP_|OPB_))",
        schema,
        sql,
        flags=re.I,
    )
    sql, subject_count = re.subn(
        r"w\.SUBJECT_AREA\s*=\s*'[^']*'",
        "w.SUBJECT_AREA = :subject_area",
        sql,
        flags=re.I,
    )
    sql, workflow_count = re.subn(
        r"w\.WORKFLOW_NAME\s*=\s*'[^']*'",
        "w.WORKFLOW_NAME = :workflow_name",
        sql,
        flags=re.I,
    )
    sql, mapplet_count = re.subn(
        r"([A-Za-z][A-Za-z0-9_]*)\.MAPPLET_INSTANCE_NAME\s*=\s*'[^']*'",
        r"UPPER(\1.MAPPLET_NAME) = UPPER(:mapplet_name)",
        sql,
        flags=re.I,
    )
    log.info("STEP 07.02 | SQL replacements. schema=%d, subject=%d, workflow=%d, mapplet=%d",
             schema_count, subject_count, workflow_count, mapplet_count)
    if mapplet_count != 1:
        raise ValueError(f"Expected one mapplet filter replacement, found {mapplet_count}")
    log.info("STEP 07.03 | SQL prepared. Original chars=%d, prepared chars=%d", original_length, len(sql))
    return sql


def execute_frame(conn, sql, binds, context="SQL query"):
    active_binds = {key: value for key, value in binds.items() if f":{key}" in sql}
    log.info("STEP 08.01 | Opening cursor for %s", context)
    log.info("STEP 08.02 | Executing %s with binds=%s", context, active_binds)
    started = time.monotonic()
    cur = conn.cursor()
    try:
        cur.execute(sql, active_binds)
        cols = [d[0] for d in cur.description]
        rows = cur.fetchall()
        frame = pd.DataFrame(rows, columns=cols)
        log.info("STEP 08.03 | Query completed. context=%s, rows=%d, columns=%d, elapsed=%.2f",
                 context, len(frame), len(cols), time.monotonic()-started)
        return frame
    except Exception:
        log.exception("STEP 08.99 | Database operation failed for %s", context)
        raise
    finally:
        cur.close()
        log.info("STEP 08.04 | Cursor closed for %s", context)


def discover_selected_mapplets(conn, schema, mapplets, subject, workflow):
    log.info("STEP 09.01 | Selected-mapplet discovery started. Mapplets=%d", len(mapplets))
    sql = build_discovery_query(schema, all_mapplets=False)
    frames, summary = [], []
    for index, name in enumerate(mapplets, 1):
        started = time.monotonic()
        log.info("STEP 09.02 | Discovery %d/%d: %s", index, len(mapplets), name)
        try:
            frame = execute_frame(conn, sql, {"subject_area":subject,"workflow_name":workflow,"mapplet_name":name},
                                  f"discovery mapplet={name}")
            if not frame.empty: frames.append(frame)
            status = "FOUND" if not frame.empty else "NO DATA"
            summary.append({"MODE":"SELECTED_MAPPLETS","MAPPLET_NAME":name,"STATUS":status,
                            "ROW_COUNT":len(frame),"ELAPSED_SECONDS":round(time.monotonic()-started,2),"ERROR_MESSAGE":""})
            log.info("STEP 09.03 | Discovery finished. mapplet=%s, status=%s, rows=%d", name,status,len(frame))
        except Exception as exc:
            log.exception("STEP 09.99 | Discovery failed for mapplet=%s", name)
            summary.append({"MODE":"SELECTED_MAPPLETS","MAPPLET_NAME":name,"STATUS":"ERROR","ROW_COUNT":0,
                            "ELAPSED_SECONDS":round(time.monotonic()-started,2),"ERROR_MESSAGE":str(exc)})
    details = pd.concat(frames,ignore_index=True).drop_duplicates() if frames else pd.DataFrame(columns=RESULT_COLUMNS)
    return details, pd.DataFrame(summary)


def discover_workflow_mapplets(conn, schema, subject, workflow):
    """Discover every mapplet and transformation used by one workflow."""
    log.info("STEP 09W.01 | Workflow-level discovery started. workflow=%s", workflow)
    started=time.monotonic()
    sql=build_discovery_query(schema, all_mapplets=True)
    try:
        details=execute_frame(conn,sql,{"subject_area":subject,"workflow_name":workflow},
                              f"workflow-wide discovery workflow={workflow}")
    except Exception as exc:
        log.exception("STEP 09W.99 | Workflow-level discovery failed")
        summary=pd.DataFrame([{"MODE":"WORKFLOW_ALL_MAPPLETS","MAPPLET_NAME":"ALL_MAPPLETS",
                              "STATUS":"ERROR","ROW_COUNT":0,"ELAPSED_SECONDS":round(time.monotonic()-started,2),
                              "ERROR_MESSAGE":str(exc)}])
        return pd.DataFrame(columns=RESULT_COLUMNS),summary
    if details.empty:
        log.warning("STEP 09W.02 | No mapplets found in workflow=%s",workflow)
        return details,pd.DataFrame([{"MODE":"WORKFLOW_ALL_MAPPLETS","MAPPLET_NAME":"ALL_MAPPLETS",
                                     "STATUS":"NO DATA","ROW_COUNT":0,"ELAPSED_SECONDS":round(time.monotonic()-started,2),
                                     "ERROR_MESSAGE":""}])
    names=sorted(details["MAPPLET_NAME"].dropna().astype(str).unique())
    log.info("STEP 09W.02 | Workflow discovery found %d mapplets and %d transformation rows",len(names),len(details))
    summary=[]
    for name in names:
        count=int((details["MAPPLET_NAME"].astype(str)==name).sum())
        summary.append({"MODE":"WORKFLOW_ALL_MAPPLETS","MAPPLET_NAME":name,"STATUS":"FOUND","ROW_COUNT":count,
                        "ELAPSED_SECONDS":round(time.monotonic()-started,2),"ERROR_MESSAGE":""})
        log.info("STEP 09W.03 | Workflow mapplet discovered: %s, transformation rows=%d",name,count)
    return details.drop_duplicates(),pd.DataFrame(summary)


def run_detail_queries(conn, schema, discovery, subject, workflow):
    outputs, statuses, executed = {}, [], set()
    log.info("STEP 10.01 | Detail phase started")
    if discovery.empty:
        log.warning("STEP 10.02 | No discovery rows. Detail phase skipped")
        return outputs,pd.DataFrame(columns=["MAPPLET_NAME","WIDGET_TYPE_NAME","QUERY_LABEL","STATUS","ROW_COUNT","ELAPSED_SECONDS","MESSAGE"])
    pairs=discovery[["MAPPLET_NAME","WIDGET_TYPE_NAME"]].drop_duplicates()
    for index,row in enumerate(pairs.itertuples(index=False),1):
        mapplet=str(row.MAPPLET_NAME); widget=str(row.WIDGET_TYPE_NAME or "").strip(); key=widget.upper()
        label=WIDGET_QUERY_MAP.get(key)
        log.info("STEP 10.03 | Evaluating %d/%d: mapplet=%s, transformation=%s",index,len(pairs),mapplet,widget)
        if not label:
            message=f"Query related to transformation '{widget}' is not configured or present in the script."
            log.warning("STEP 10.04 | %s Mapplet=%s",message,mapplet)
            statuses.append({"MAPPLET_NAME":mapplet,"WIDGET_TYPE_NAME":widget,"QUERY_LABEL":"",
                             "STATUS":"QUERY NOT CONFIGURED","ROW_COUNT":0,"ELAPSED_SECONDS":0,"MESSAGE":message})
            continue
        if label not in EXCEL_QUERIES or not str(EXCEL_QUERIES.get(label,"")).strip():
            message=f"Query related to transformation '{widget}' is mapped to '{label}', but the query is not configured or present in the script."
            log.warning("STEP 10.05 | %s Mapplet=%s",message,mapplet)
            statuses.append({"MAPPLET_NAME":mapplet,"WIDGET_TYPE_NAME":widget,"QUERY_LABEL":label,
                             "STATUS":"QUERY NOT PRESENT","ROW_COUNT":0,"ELAPSED_SECONDS":0,"MESSAGE":message})
            continue
        run_key=(mapplet,label)
        if run_key in executed:
            log.info("STEP 10.06 | Duplicate category execution skipped: mapplet=%s, label=%s",mapplet,label.replace("\n"," | "))
            continue
        executed.add(run_key); started=time.monotonic()
        try:
            sql=prepare_excel_query(EXCEL_QUERIES[label],schema)
            frame=execute_frame(conn,sql,{"subject_area":subject,"workflow_name":workflow,"mapplet_name":mapplet},
                                f"detail mapplet={mapplet}, transformation={widget}")
            if not frame.empty: outputs.setdefault(label,[]).append(frame)
            status="OUTPUT" if not frame.empty else "NO OUTPUT"
            statuses.append({"MAPPLET_NAME":mapplet,"WIDGET_TYPE_NAME":widget,"QUERY_LABEL":label,"STATUS":status,
                             "ROW_COUNT":len(frame),"ELAPSED_SECONDS":round(time.monotonic()-started,2),"MESSAGE":""})
            log.info("STEP 10.07 | Detail finished. mapplet=%s, label=%s, status=%s, rows=%d",mapplet,label.replace("\n"," | "),status,len(frame))
        except Exception as exc:
            log.exception("STEP 10.99 | Detail query failed. mapplet=%s, transformation=%s",mapplet,widget)
            statuses.append({"MAPPLET_NAME":mapplet,"WIDGET_TYPE_NAME":widget,"QUERY_LABEL":label,"STATUS":"ERROR",
                             "ROW_COUNT":0,"ELAPSED_SECONDS":round(time.monotonic()-started,2),"MESSAGE":str(exc)})
    combined={}
    for label,frames in outputs.items():
        combined[label]=pd.concat(frames,ignore_index=True).drop_duplicates()
        log.info("STEP 10.08 | Combined transformation tab=%s, rows=%d",label.replace("\n"," | "),len(combined[label]))
    return combined,pd.DataFrame(statuses)


SHEET_LABELS={
 "EXPRESSION":"Expression","FILTERS":"Filter","LOOKUP":"Lookup","Sequne gen":"Sequence_Generator",
 "JOINER":"Joiner","Sorter":"Sorter","Output Tras":"Output_Transformation","Input Trans":"Input_Transformation",
 "Router":"Router","Aggregator":"Aggregator","Source Qualifier":"Source_Qualifier","Source Definition":"Source_Definition"
}

def safe_sheet_name(label,used):
    preferred=SHEET_LABELS.get(label)
    if not preferred:
        if label.startswith("Custome Trans are:"): preferred="Custom_Transformations"
        else: preferred=label.replace("\n"," ")
    base=re.sub(r"[\[\]:*?/\\]","_",preferred).strip()[:31] or "Details"
    name=base; i=2
    while name in used:
        suffix=f"_{i}"; name=base[:31-len(suffix)]+suffix; i+=1
    used.add(name); return name


def format_sheet(ws,df):
    from openpyxl.styles import Alignment,Font,PatternFill
    from openpyxl.utils import get_column_letter
    for c in ws[1]:
        c.fill=PatternFill("solid",fgColor="1F4E78"); c.font=Font(color="FFFFFF",bold=True); c.alignment=Alignment(horizontal="center")
    ws.freeze_panes="A2"; ws.auto_filter.ref=ws.dimensions
    for i,col in enumerate(df.columns,1):
        vals=df[col].fillna("").astype(str).tolist()[:3000]
        ws.column_dimensions[get_column_letter(i)].width=min(max([len(str(col))]+[len(x) for x in vals])+2,70)


def write_excel(path,discovery,summary,outputs,status):
    """Guarantee: first tab discovery, middle tabs transformation details, final two tabs summaries."""
    p=Path(path); p.parent.mkdir(parents=True,exist_ok=True); used=set(); started=time.monotonic()
    log.info("STEP 13.01 | Writing workbook with enforced tab order: %s",p.resolve())
    with pd.ExcelWriter(p,engine="openpyxl") as writer:
        # First tab, always.
        discovery.to_excel(writer,sheet_name="Mapplet_Transformations",index=False)
        used.add("Mapplet_Transformations"); format_sheet(writer.sheets["Mapplet_Transformations"],discovery)
        log.info("STEP 13.02 | First tab written: Mapplet_Transformations")
        # Middle tabs, one per transformation category, aggregated across all mapplets.
        for label,frame in outputs.items():
            name=safe_sheet_name(label,used)
            frame.to_excel(writer,sheet_name=name,index=False); format_sheet(writer.sheets[name],frame)
            log.info("STEP 13.03 | Transformation tab written: %s, rows=%d",name,len(frame))
        # Final two tabs, always and in this order.
        summary.to_excel(writer,sheet_name="Execution_Summary",index=False)
        format_sheet(writer.sheets["Execution_Summary"],summary)
        status.to_excel(writer,sheet_name="Query_Status",index=False)
        format_sheet(writer.sheets["Query_Status"],status)
        log.info("STEP 13.04 | Final tabs written: Execution_Summary, Query_Status")
    log.info("STEP 13.05 | Workbook saved in %.2f seconds",time.monotonic()-started)
    return p


def parse_args():
    """Parse and validate mode-specific mandatory runtime parameters."""
    parser = argparse.ArgumentParser(
        description=(
            "Extract Informatica mapplet transformation details. "
            "Workflow mode requires subject area and workflow name. "
            "Per-mapplet mode additionally requires mapplet name."
        )
    )
    parser.add_argument("--config", default="config.json")
    parser.add_argument(
        "--subject-area", "-subject_area",
        dest="subject_area",
        required=True,
        help="Required Informatica subject area/folder name",
    )
    parser.add_argument(
        "--workflow", "-workflow", "--workflow-name", "-workflow_name",
        dest="workflow",
        required=True,
        help="Required Informatica workflow name",
    )
    parser.add_argument(
        "--mapplet-name", "-mapplet_name",
        dest="mapplet_name",
        default=None,
        help="Required in per-mapplet mode; ignored in workflow all-mapplet mode",
    )
    parser.add_argument(
        "-for", "--for",
        dest="selection",
        choices=["all_mapplet"],
        default=None,
        help="Set to all_mapplet to process every mapplet in the specified workflow",
    )
    parser.add_argument("--output", default=None)
    parser.add_argument("--log-file", default=None)
    args = parser.parse_args()
    args.workflow_mode = args.selection == "all_mapplet"

    if args.workflow_mode and args.mapplet_name:
        parser.error("--mapplet-name/-mapplet_name cannot be used with -for all_mapplet")
    if not args.workflow_mode and not args.mapplet_name:
        parser.error(
            "Per-mapplet mode requires --mapplet-name/-mapplet_name together with "
            "--subject-area and --workflow"
        )

    log.info(
        "STEP 00.02 | Arguments validated. mode=%s, subject_area=%s, workflow=%s, mapplet=%s",
        "WORKFLOW_ALL_MAPPLETS" if args.workflow_mode else "PER_MAPPLET",
        args.subject_area,
        args.workflow,
        args.mapplet_name or "ALL_MAPPLETS",
    )
    return args

def main():
    process_started=time.monotonic(); connection=None
    log.info("STEP 00.00 | Extraction process started")
    args=parse_args(); timestamp=datetime.now().strftime("%Y%m%d_%H%M%S")
    try:
        config=load_config(args.config); options=config.get("options",{}); folder=Path(options.get("output_folder","./output")); folder.mkdir(parents=True,exist_ok=True)
        mode_suffix="all_mapplets" if args.workflow_mode else "selected_mapplets"
        output=args.output or str(folder/f"{args.workflow}_{mode_suffix}_transformation_details.xlsx")
        configure_file_logging(args.log_file or str(folder/f"{args.workflow}_{mode_suffix}_{timestamp}.log"))
        log.info("STEP 01.03 | Mode=%s, output=%s","WORKFLOW LEVEL" if args.workflow_mode else "SELECTED MAPPLET",Path(output).resolve())
        schema=normalize_schema_prefix(options.get("schema_prefix","M2R_REP_1053_P01."))
        connection=connect(config)
        if args.workflow_mode:
            log.info(
                "STEP 09W.00 | Workflow-level mode enabled. subject_area=%s, workflow=%s",
                args.subject_area,
                args.workflow,
            )
            discovery,summary=discover_workflow_mapplets(connection,schema,args.subject_area,args.workflow)
            mapplet_count=int(discovery["MAPPLET_NAME"].nunique()) if not discovery.empty else 0
        else:
            log.info(
                "STEP 09.00 | Per-mapplet mode enabled. subject_area=%s, workflow=%s, mapplet=%s",
                args.subject_area,
                args.workflow,
                args.mapplet_name,
            )
            discovery, summary = discover_selected_mapplets(
                connection,
                schema,
                [args.mapplet_name],
                args.subject_area,
                args.workflow,
            )
            mapplet_count = 1
        outputs,status=run_detail_queries(connection,schema,discovery,args.subject_area,args.workflow)
        write_excel(output,discovery,summary,outputs,status)
        discovery_errors=int((summary.get("STATUS",pd.Series(dtype=str))=="ERROR").sum())
        detail_errors=int((status.get("STATUS",pd.Series(dtype=str))=="ERROR").sum())
        not_configured=int(status.get("STATUS",pd.Series(dtype=str)).isin(["QUERY NOT CONFIGURED","QUERY NOT PRESENT"]).sum())
        log.info("STEP 14.01 | Completed. mapplets=%d, discovery_rows=%d, tabs=%d, query_not_configured=%d, errors=%d",
                 mapplet_count,len(discovery),len(outputs),not_configured,discovery_errors+detail_errors)
        log.info("STEP 14.02 | Output workbook: %s",Path(output).resolve())
        return 1 if discovery_errors+detail_errors else 0
    except Exception:
        log.exception("STEP 99.99 | Extraction failed after %.2f seconds",time.monotonic()-process_started); return 1
    finally:
        if connection is not None:
            try: connection.close(); log.info("STEP 15.02 | Oracle connection closed")
            except Exception: log.exception("STEP 15.99 | Connection close failed")
        log.info("STEP 15.04 | Cleanup completed. elapsed=%.2f",time.monotonic()-process_started)


if __name__=="__main__": sys.exit(main())
